commands.cmd:
mkdir -p /tmp/ledger && cat > /tmp/ledger/index.mjs <<'EOF'
import { DynamoDBClient, PutItemCommand } from "@aws-sdk/client-dynamodb";
const db = new DynamoDBClient({});
export const handler = async (event) => {
  for (const r of event.Records) {
    const body = JSON.parse(r.body);
    if (!body.page) throw new Error("no page");
    await db.send(new PutItemCommand({ TableName: process.env.TABLE, Item: { id: { S: `visit#${r.messageId}` }, page: { S: body.page }, at: { N: String(Date.now()) } } }));
  }
};
EOF
cd /tmp/ledger && zip -q f.zip index.mjs && sleep 10 && aws lambda create-function --function-name capstone-team01-ledger --runtime nodejs20.x --handler index.handler --role arn:aws:iam::$ACCT:role/role-ledger-team01 --zip-file fileb://f.zip --environment Variables={TABLE=capstone-team01-visitors} --query State --output text
